alter table vendedores add column if not exists funcao text default 'vendedor_industria',add column if not exists vinculo text default 'clt',add column if not exists status_vendedor text default 'ativo',add column if not exists data_entrada date,add column if not exists gestor_id bigint,add column if not exists tutor_id bigint,add column if not exists academia_fase text not null default 'formacao',add column if not exists academia_termo_versao text,add column if not exists academia_termo_aceito_em timestamptz;
update vendedores set academia_fase='reciclagem';
create table if not exists academia_competencias (id bigint generated by default as identity primary key,grupo text not null,nome text not null,ordem integer default 0,ativo boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists academia_blocos (id bigint generated by default as identity primary key,ordem integer not null,nome text not null,nota_corte integer default 70,prazo_dias integer,ativo boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists academia_biblioteca (id bigint generated by default as identity primary key,titulo text not null,secao text not null,segmento text,produto_id bigint,tipo text default 'texto',conteudo text,url text,responsavel text,status text default 'rascunho',interno boolean default false,atualizado_em timestamptz default now(),created_at timestamptz default now());
create table if not exists academia_aulas (id bigint generated by default as identity primary key,bloco_id bigint references academia_blocos(id) on delete cascade,biblioteca_id bigint,titulo text not null,tipo text default 'texto',conteudo text,funcoes text[] default '{}',ordem integer default 0,ativo boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists academia_questoes (id bigint generated by default as identity primary key,bloco_id bigint references academia_blocos(id) on delete cascade,tipo text default 'quiz',pergunta text not null,alternativas jsonb default '[]',resposta_correta text,competencia_id bigint,funcoes text[] default '{}',ordem integer default 0,ativo boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists academia_chaves (codigo text primary key,nome text not null,descricao text,ordem integer default 0);
create table if not exists academia_chaves_funcao (funcao text not null,chave text not null,ativo boolean default false,updated_at timestamptz default now(),primary key(funcao,chave));
create table if not exists academia_chaves_pessoa (vendedor_id bigint not null,chave text not null,ativo boolean not null,updated_at timestamptz default now(),primary key(vendedor_id,chave));
create table if not exists academia_progresso (id bigint generated by default as identity primary key,vendedor_id bigint not null,bloco_id bigint not null,estado text default 'disponivel',etapa_atual text default 'aulas',nota integer,competencias_abaixo jsonb default '[]',notas_competencias jsonb default '{}',iniciado_em timestamptz,concluido_em timestamptz,ultima_atividade_em timestamptz default now(),unique(vendedor_id,bloco_id));
create table if not exists academia_termos (id bigint generated by default as identity primary key,funcao text,vinculo text not null,versao text not null,pdf_url text not null,ativo boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists academia_termos_aceites (id bigint generated by default as identity primary key,vendedor_id bigint not null,termo_id bigint not null,versao text not null,aceito_em timestamptz default now());
create table if not exists academia_treinos_atribuidos (id bigint generated by default as identity primary key,vendedor_id bigint not null,titulo text not null,descricao text,status text default 'pendente',atribuido_por bigint,atribuido_em timestamptz default now(),concluido_em timestamptz);
create table if not exists academia_um_a_um (id bigint generated by default as identity primary key,vendedor_id bigint not null,gerente_id bigint,data date default current_date,texto text not null,created_at timestamptz default now());
create table if not exists academia_historico (id bigint generated by default as identity primary key,entidade text not null,entidade_id text,vendedor_id bigint,acao text not null,campo text,valor_anterior text,valor_novo text,alterado_por bigint,alterado_por_nome text,alterado_em timestamptz default now());
insert into academia_competencias(grupo,nome,ordem) select * from (values ('Comunicação','Clareza da fala',1),('Comunicação','Objetividade',2),('Comunicação','Ritmo e vícios de linguagem',3),('Comunicação','Escrita',4),('Condução','Abertura',5),('Condução','Escuta e perguntas',6),('Condução','Qualificação',7),('Condução','Próximo passo',8),('Conhecimento','Produto e aplicação',9),('Conhecimento','Processo de fabricação do cliente',10),('Conhecimento','Concorrentes',11),('Conhecimento','Matemática comercial',12),('Negociação','Tratamento de objeções',13),('Negociação','Defesa de preço e valor',14),('Negociação','Fechamento',15),('Disciplina','Registro no CRM',16),('Disciplina','Follow-up',17),('Disciplina','Cumprimento de agenda',18),('Conduta','Não prometer fora da política',19),('Conduta','Honestidade sobre o que não sabe',20)) x(grupo,nome,ordem) where not exists(select 1 from academia_competencias);
insert into academia_blocos(ordem,nome,nota_corte,prazo_dias) select * from (values (1,'Empresa',70,7),(2,'Legislação',70,7),(3,'Produtos',70,7),(4,'Cliente e como ele produz',70,7),(5,'Concorrentes',70,7),(6,'Canais de venda',70,7),(7,'Contorno de objeções',70,7),(8,'Processos internos',70,7)) x(ordem,nome,nota_corte,prazo_dias) where not exists(select 1 from academia_blocos);
insert into academia_chaves(codigo,nome,ordem) values ('acesso','Acesso à Academia',1),('trilha_obrigatoria','Trilha obrigatória',2),('prazo_bloco','Prazo por bloco',3),('alerta_atraso','Alerta de atraso para o gerente',4),('cobranca_inicio','Cobrança de pendências no Início',5),('treino_atribuido','Treino atribuído pelo gerente',6),('termo_exigido','Termo de responsabilidade exigido',7),('liberacao_campo','Liberação para campo pelo gerente',8),('aparece_ranking','Aparece no ranking',9),('elegivel_premio','Elegível a prêmio',10) on conflict(codigo) do nothing;
insert into academia_chaves_funcao(funcao,chave,ativo) select f,c.codigo,case when f='rca' then c.codigo in('acesso','termo_exigido') else true end from (values('vendedor_industria'),('executiva_contas'),('interno'),('rca')) x(f) cross join academia_chaves c on conflict do nothing;
alter table academia_competencias enable row level security;drop policy if exists permissive_all on academia_competencias;create policy permissive_all on academia_competencias for all to authenticated,anon,service_role using(true) with check(true);
