alter table academia_progresso add column if not exists notas_competencias jsonb default '{}';
insert into academia_biblioteca(titulo,secao,produto_id,tipo,conteudo,responsavel,status,interno)
select p.nome,'Produtos',p.id,'texto',concat_ws(E'\n',p.descricao,nullif(p.categoria,''),case when p.sku is not null then 'SKU: '||p.sku end),'Migração automática','rascunho',false
from produtos p
where not exists(select 1 from academia_biblioteca b where b.produto_id=p.id);
